# Set SEER_ANALYSIS_ROOT to the locally authorized input project.
source('work/revision_20261019/engine.R');source('work/cbc_chain_extension/predict_fast.R');setDTthreads(1)
z<-load_data();ref<-z[sex=='Male'&year>=2015&stage!='Unknown'&grade!='Unknown'&er!='Unknown',.N,by=vars];ref[,weight:=N/sum(N)];st<-readRDS(file.path(outroot,'private_imputations','smc_c1_i01.rds'));for(v in c('stage','grade','er'))ref[,(v):=factor(get(v),levels=levels(st[[v]]))];rr<-list()
for(c in 1:4)for(i in 1:10){label<-sprintf('smc_c%d_i%02d',c,i);ff<-readRDS(file.path(outroot,'fits',paste0(label,'.rds')))$fits;V<-make_V(ff);m<-predict_joint_fast(ff,ref,'Male');f<-predict_joint_fast(ff,ref,'Female');aa<-list(Male=m,Female=f,Difference=list(est=m$est-f$est,G=m$G-f$G));for(ss in names(aa)){a<-aa[[ss]];rr[[length(rr)+1]]<-data.table(model=label,sex=ss,outcome=names(a$est),estimate=a$est,se=sqrt(pmax(0,rowSums((a$G%*%V)*a$G))))}}
x<-rbindlist(rr);fwrite(x,'work/jjco_robustness_final/shared_reference_per_imputation.csv');p<-x[, {B<-var(estimate);T<-mean(se^2)+(1+1/.N)*B;lam<-(1+1/.N)*B/T;df<-if(B<1e-18)Inf else (.N-1)/lam^2;list(estimate=mean(estimate),se=sqrt(T),lower=mean(estimate)-qt(.975,df)*sqrt(T),upper=mean(estimate)+qt(.975,df)*sqrt(T))},by=.(sex,outcome)];fwrite(p,'work/jjco_robustness_final/shared_reference_pooled.csv');print(p[sex=='Difference'])
